<script lang="ts">
 const features = [
  { number: '01', title: 'Remembers what matters.', text: 'Your people, preferences, and projects. Nolune carries context from one conversation to the next, with memories you can read and edit.' },
  { number: '02', title: 'A little more proactive.', text: 'Set a routine, schedule a check-in, or ask for a morning brief. Nolune can keep useful work moving while its server is running.' },
  { number: '03', title: 'Yours from the start.', text: 'Your hardware. Your choice of models. Your companion’s personality. Open source, with no required Nolune cloud account.' }
 ];
 const steps = [
  { title: 'Give it a home.', text: 'Install the Nolune server on an always-on Mac or Linux computer. This is where its identity and memory live.' },
  { title: 'Connect your computers.', text: 'Add the desktop app to the machines you want Nolune to work on. You choose which permissions to grant.' },
  { title: 'Make it yours.', text: 'Connect your model provider, shape its personality, and start a conversation. Your companion grows with you.' }
 ];
 const faqs = [
  { q: 'What is Nolune?', a: 'Nolune is an open-source, self-hosted AI companion. It has a persistent identity, long-term memory, and tools to work across computers you connect.' },
  { q: 'Where does Nolune run?', a: 'The server runs on macOS or Linux. Desktop apps for macOS, Windows, and Linux connect to that server, so you can work with the same companion across your computers. You can also access its web interface from your phone’s browser when your Nolune server is reachable.' },
  { q: 'Is Nolune free?', a: 'Nolune is MIT-licensed open-source software. Bring your own model provider API key; that provider’s pricing and usage limits apply.' },
  { q: 'Can Nolune use my computer?', a: 'Yes. On connected computers, Nolune can see the screen, use apps, work with files, and run commands. You choose which computers to connect and grant the operating-system permissions they need.' },
  { q: 'Where is my data stored?', a: 'Identity, memories, and conversation history live on the hardware where you run the Nolune server. When you use an external model or integration, the data needed for that request is sent to that provider.' }
 ];
